'use client';import {useState} from 'react';import {Pencil,Plus,Search,Trash2,Upload} from 'lucide-react';import {categories,Product,money} from '@/lib/data';import {useStore} from '@/lib/store';import {Panel,Toolbar} from '@/components/Panel';
const blank:Product={id:0,name:'',category:categories[0],price:0,expense:0,stock:0,image:'',active:true};
export default function Products(){const{products,setProducts,toast,role}=useStore();const[form,setForm]=useState<Product>(blank);const[edit,setEdit]=useState<number|null>(null);const[q,setQ]=useState('');const data=products.filter(p=>(p.name+' '+p.category).toLowerCase().includes(q.toLowerCase()));function save(){if(!form.name||!form.price){toast('Enter product name and price');return}if(edit!==null)setProducts(v=>v.map(p=>p.id===edit?{...form,id:edit}:p));else setProducts(v=>[...v,{...form,id:Date.now()}]);setForm(blank);setEdit(null);toast(edit!==null?'Product updated':'Product added')}function remove(id:number){if(confirm('Delete this product?')){setProducts(v=>v.filter(p=>p.id!==id));toast('Product deleted')}}return <><Toolbar title="Products" subtitle="Add, edit and manage products shown on the customer homepage"/><div className="two-col"><Panel><h3>{edit!==null?'Edit Product':'Add New Product'}</h3><div className="form-grid"><label>Category<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label>Product Name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Selling Price (₹)<input type="number" value={form.price||''} onChange={e=>setForm({...form,price:Number(e.target.value)})}/></label>{role==='admin'&&<label>Expense / Cost (₹)<input type="number" value={form.expense||''} onChange={e=>setForm({...form,expense:Number(e.target.value)})}/></label>}<label>Stock Quantity<input type="number" value={form.stock||''} onChange={e=>setForm({...form,stock:Number(e.target.value)})}/></label><label>Image URL<input value={form.image} onChange={e=>setForm({...form,image:e.target.value})} placeholder="https://..."/></label></div><div className="upload"><Upload size={25}/><span>For Codespaces demo, paste an image URL above.</span></div><div className="modal-actions"><button onClick={()=>{setForm(blank);setEdit(null)}}>Clear</button><button className="primary-btn" onClick={save}><Plus/> {edit!==null?'Update Product':'Add Product'}</button></div></Panel><Panel><div className="filterbar"><div className="search-box dark"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products..."/></div></div><div className="table-card"><table><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th>{role==='admin'&&<th>Expense</th>}<th>Stock</th><th>Action</th></tr></thead><tbody>{data.map(p=><tr key={p.id}><td><img className="thumb" src={p.image}/></td><td><b>{p.name}</b></td><td>{p.category}</td><td>{money(p.price)}</td>{role==='admin'&&<td>{money(p.expense)}</td>}<td>{p.stock}</td><td><div className="row-actions"><button onClick={()=>{setForm(p);setEdit(p.id)}}><Pencil size={15}/></button><button className="danger" onClick={()=>remove(p.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div></Panel></div></>}
